package com.klikli_dev.occultism.client.model.entity;
import com.klikli_dev.occultism.client.render.entity.state.BeholderFamiliarRenderState; import com.google.common.collect.ImmutableList; import net.minecraft.client.model.*; import net.minecraft.client.model.geom.*; import net.minecraft.client.model.geom.builders.*; import net.minecraft.util.Mth; import net.minecraft.world.phys.Vec2; import java.util.List;
public class BeholderFamiliarModel extends EntityModel<BeholderFamiliarRenderState>{ private static final float PI=(float)Math.PI; public ModelPart head,eye11,mouth,bigEye,spike1,spike2,upperTeeth1,upperTeeth2,spike3,spike4,spike5,spike6,upperTeeth3,eye21,eye31,eye41,glasses,eye12,eye13,eye14,eye15,beard,lowerTeeth1,lowerTeeth2,lowerTeeth3,tongue,bigPupil,eye22,eye23,eye24,eye25,eye32,eye33,eye34,eye35,eye42,eye43,eye44,eye45; public BeholderFamiliarModel(ModelPart p){super(p); head=p.getChild("head"); eye11=head.getChild("eye11"); mouth=head.getChild("mouth"); bigEye=head.getChild("bigEye"); spike1=head.getChild("spike1"); spike2=head.getChild("spike2"); upperTeeth1=head.getChild("upperTeeth1"); upperTeeth2=head.getChild("upperTeeth2"); spike3=head.getChild("spike3"); spike4=head.getChild("spike4"); spike5=head.getChild("spike5"); spike6=head.getChild("spike6"); upperTeeth3=head.getChild("upperTeeth3"); eye21=head.getChild("eye21"); eye31=head.getChild("eye31"); eye41=head.getChild("eye41"); glasses=head.getChild("glasses"); eye12=eye11.getChild("eye12"); eye13=eye12.getChild("eye13"); eye14=eye13.getChild("eye14"); eye15=eye14.getChild("eye15"); beard=mouth.getChild("beard"); lowerTeeth1=mouth.getChild("lowerTeeth1"); lowerTeeth2=mouth.getChild("lowerTeeth2"); lowerTeeth3=mouth.getChild("lowerTeeth3"); tongue=mouth.getChild("tongue"); bigPupil=bigEye.getChild("bigPupil"); eye22=eye21.getChild("eye22"); eye23=eye22.getChild("eye23"); eye24=eye23.getChild("eye24"); eye25=eye24.getChild("eye25"); eye32=eye31.getChild("eye32"); eye33=eye32.getChild("eye33"); eye34=eye33.getChild("eye34"); eye35=eye34.getChild("eye35"); eye42=eye41.getChild("eye42"); eye43=eye42.getChild("eye43"); eye44=eye43.getChild("eye44"); eye45=eye44.getChild("eye45"); }
public static LayerDefinition createBodyLayer(){return null;} @Override public void setupAnim(BeholderFamiliarRenderState s){super.setupAnim(s); tongue.visible=s.hasTongue; beard.visible=s.hasBeard; spike1.visible=spike2.visible=spike3.visible=spike4.visible=spike5.visible=spike6.visible=s.hasSpikes; bigPupil.visible=!s.isSitting; glasses.visible=s.hasBlacksmithUpgrade; setRotateAngle(head,0,0,0); setEyeRot(s,ImmutableList.of(eye11,eye12,eye13,eye14),0); setEyeRot(s,ImmutableList.of(eye21,eye22,eye23,eye24),1); setEyeRot(s,ImmutableList.of(eye31,eye32,eye33,eye34),2); setEyeRot(s,ImmutableList.of(eye41,eye42,eye43,eye44),3); bigPupil.x=s.bigEyePos.x; bigPupil.y=s.bigEyePos.y-0.5f; mouth.xRot=s.mouthRot; if(s.isPartying){float e=-Mth.cos(s.ageInTicks*0.2f)*toRads(15); for(ModelPart m:ImmutableList.of(eye11,eye12,eye13,eye14,eye21,eye22,eye23,eye24,eye31,eye32,eye33,eye34,eye41,eye42,eye43,eye44)){m.yRot=0;m.xRot=e;} head.xRot=Mth.cos(s.ageInTicks*0.2f)*toRads(20); head.yRot=Mth.cos(s.ageInTicks*0.2f+PI)*toRads(20); head.zRot=Mth.cos(s.ageInTicks*0.1f)*toRads(30);} else if(s.isSitting){head.zRot=toRads(90); mouth.xRot=toRads(20);} }
private void setEyeRot(BeholderFamiliarRenderState s,List<ModelPart> m,int i){Vec2 r=s.eyeRot[i]; for(int j=0;j<m.size();j++){m.get(j).xRot=r.x; m.get(j).zRot=0; m.get(j).yRot=0;} m.get(0).xRot=0; m.get(0).yRot=r.y;} private float toRads(float d){return PI/180f*d;} public void setRotateAngle(ModelPart m,float x,float y,float z){m.xRot=x;m.yRot=y;m.zRot=z;}}
